#include <iostream>
#include <string>
#include <vector>

struct Lectura {
    std::string sitio;
    int personas;
};

int doble(int cantidad) {
    return cantidad * 2;
}

int main() {
    Lectura registro{"Este", 4};
    int total = doble(registro.personas);
    std::cout << registro.personas << " " << total;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct Registro {
    std::string codigo;
    int unidades;
};

void probar(const std::string& codigo, int unidades) {
    Registro original{codigo, unidades};
    std::cout << original.codigo << ":" << original.unidades << "\n";
    Registro copia = original;
    original.unidades += 3;
    std::cout << "Original " << original.codigo << ":" << original.unidades << "\n";
    std::cout << "Copia " << copia.codigo << ":" << copia.unidades << "\n";
}

int main() {
    probar("R4", 6);
    probar("S0", 0);
    return 0;
}
